mapper.select:
select k.label as city,purchaseNum + biddingNum as totalNum, purchaseBudget + biddingBudget as totalBudget,
       purchaseKnowNum + biddingKnowNum as totalKnowNum, purchaseKnowBudget + biddingKnowBudget as totalKnowBudget,
       CONCAT(ROUND(ifnull(purchaseKnowNum + biddingKnowNum,0) * 100 / (purchaseNum + biddingNum), 0), '%') as totalNumPercent,
       purchaseNum, purchaseBudget, purchaseKnowNum, purchaseKnowBudget, purchaseNumPercent, biddingNum, biddingBudget, biddingKnowNum, biddingKnowBudget, biddingNumPercent
from (
         select label, p.num as purchaseNum, p.bidding_budget as purchaseBudget,
                if(pknow.num is null and p.num is not null, 0, pknow.num) as purchaseKnowNum,
                if(pknow.bidding_budget is null and p.bidding_budget is not null, 0, pknow.num) as purchaseKnowBudget,
                CONCAT(ROUND(ifnull(pknow.num,0) * 100 / p.num, 0), '%') as purchaseNumPercent,
                b.num as biddingNum,
                b.bidding_budget as biddingBudget,
                if(bknow.num is null and b.num is not null, 0, bknow.num) as biddingKnowNum,
                if(bknow.bidding_budget is null and b.bidding_budget is not null, 0, bknow.num) as biddingKnowBudget,
                CONCAT(ROUND(ifnull(bknow.num,0) * 100 / b.num, 0), '%') as biddingNumPercent
        from chatbi.bid_dict_data dict
        left join (select city, count(1) num, round(bidding_budget/10000, 0) bidding_budget
                 from chatbi.bid_biz_purchase_intention
                 where province=#{province} and publish_time between #{weekStartTime} and #{weekEndTime}
                 group by city) p on convert(dict.value using utf8mb4) collate utf8mb4_general_ci = p.city
        left join(select city, count(1) num, round(bidding_budget/10000, 0) bidding_budget
                from chatbi.bid_biz_purchase_intention t
                join chatbi.bid_business a
                where a.id = t.bid_bus_id and t.province=#{province} and t.publish_time between #{weekStartTime} and #{weekEndTime}
                group by city) pknow on pknow.city = p.city
        left join (select city, count(1) num, round(bidding_budget/10000, 0) bidding_budget
                 from chatbi.bid_biz_bidding t
                 where t.publish_time and t.province=#{province} between #{weekStartTime} and #{weekEndTime}
                 group by city) b on b.city = p.city
        left join(select city, count(1) num, round(bidding_budget/10000, 0) bidding_budget
                from chatbi.bid_biz_bidding t
                join chatbi.bid_business a
                where a.id = t.bid_bus_id and t.province=#{province}
                and t.publish_time between #{weekStartTime} and #{weekEndTime}
                group by city) bknow on bknow.city = p.city
         where dict_type = 'bid_statistics_city' and dict.province=#{province}
         order by sort
     ) k
